"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[918],{918:e=>{e.exports=JSON.parse('{"meta":{"title":"Cocoso — Software de Coopera\xe7\xe3o Comunit\xe1ria","description":"Software de c\xf3digo aberto para federa\xe7\xf5es de comunidades, cooperativas e grupos de base — calend\xe1rio, recursos, eventos, grupos, p\xe1ginas compon\xedveis e muito mais, sempre nos seus pr\xf3prios termos."},"brand":{"title":"COCOSO","slogan":"Software de Coopera\xe7\xe3o Comunit\xe1ria"},"nav":{"home":"In\xedcio","features":"Funcionalidades","examples":"Exemplos","contact":"Contato","sourceCode":"C\xf3digo-Fonte","getStarted":"Explorar Funcionalidades","demo":"Demo ao Vivo","language":"Idioma"},"home":{"leadTitle":"Software para Comunidades Aut\xf4nomas e Federadas","lead":["O Cocoso \xe9 um software de c\xf3digo aberto para comunidades aut\xf4nomas: um site p\xfablico e uma intranet, tudo em um s\xf3 lugar. Ele foi criado para cooperativas, ecovilas, espa\xe7os autogeridos por artistas, festivais e grupos de base que querem tocar suas pr\xf3prias opera\xe7\xf5es, do seu pr\xf3prio jeito.","Um \xfanico login. V\xe1rias comunidades. Seus dados, sempre seus."],"leadTags":["Plataformas Online","Cooperativas","Organiza\xe7\xf5es Sem Fins Lucrativos","Festivais","Confer\xeancias","Espa\xe7os Autogeridos por Artistas","Ecovilas","Comunidades","Campings"],"tripleTitle":"Mais do que um Site","tripleTags":["Site P\xfablico","Rede Comunit\xe1ria","Ferramenta de Produtividade"],"triple":["O Cocoso \xe9 um site p\xfablico, para que o mundo veja quem voc\xeas s\xe3o, o que fazem e o que est\xe1 por vir — sem precisar de um site separado.","Tamb\xe9m \xe9 uma rede comunit\xe1ria privada: os membros podem acompanhar atividades, compartilhar novidades e ficar em contato uns com os outros — sem an\xfancios, algoritmos ou rastreamento. Rede social, sem a explora\xe7\xe3o de dados.","E \xe9 uma verdadeira ferramenta de produtividade para o lado pr\xe1tico de tocar uma comunidade: um calend\xe1rio compartilhado, reservas de recursos, confirma\xe7\xf5es de presen\xe7a e ferramentas de administra\xe7\xe3o que mant\xeam todo mundo na mesma p\xe1gina."],"federationTitle":"Federa\xe7\xe3o","federationTags":["Rede Multicomunit\xe1ria","Portal","Descoberta Compartilhada","Aut\xf4noma por Padr\xe3o"],"federation":["O Cocoso n\xe3o \xe9 limitado a um \xfanico grupo. Uma \xfanica instala\xe7\xe3o pode hospedar uma federa\xe7\xe3o inteira de comunidades independentes — cada uma com seu pr\xf3prio dom\xednio, sua pr\xf3pria identidade visual, seus pr\xf3prios membros — permanecendo vis\xedvel como parte de uma rede maior.","Uma federa\xe7\xe3o pode escolher uma comunidade para ser o seu Portal: uma porta de entrada compartilhada, onde visitantes navegam por todas as comunidades membros, filtram atividades em toda a rede e encontram seu caminho. Cada uma mant\xe9m sua independ\xeancia; a rede mant\xe9m sua coes\xe3o.","\xc9 uma solu\xe7\xe3o natural para um movimento formado por muitos grupos aut\xf4nomos — como uma rede de ecovilas, cooperativas ou iniciativas de base que querem estar juntas sem abrir m\xe3o da autogest\xe3o local."],"accountsTitle":"Um Login, V\xe1rias Comunidades","accountsTags":["Contas Globais","Pap\xe9is por Comunidade","Identidade Port\xe1til","Associa\xe7\xe3o Verificada"],"accounts":["Cada pessoa tem uma \xfanica conta Cocoso, onde quer que suas comunidades estejam. Entre em uma cooperativa aqui, um festival ali, uma ecovila em outro lugar — uma identidade s\xf3, que te acompanha, enquanto seu papel e visibilidade s\xe3o definidos separadamente em cada lugar.","Os administradores verificam os membros comunidade por comunidade, concedendo o direito de publicar atividades, tocar um grupo ou gerenciar recursos localmente — sem nunca precisar mexer nas configura\xe7\xf5es ou nos membros de outra comunidade."],"dataTitle":"Seus Dados S\xe3o Seus","dataTags":["Sem Rastreamento","Sem Terceiros","Soberania de Dados","Privacidade desde o In\xedcio"],"data":["O Cocoso n\xe3o tem ferramentas para espionar usu\xe1rios ou rastrear seus dados. Nenhuma informa\xe7\xe3o \xe9 compartilhada com servi\xe7os de terceiros ou anunciantes — os dados pertencem \xe0 comunidade que os criou, ponto final.","Cada membro decide quanto de sua pr\xf3pria informa\xe7\xe3o compartilhar, e cada comunidade decide quanto de sua atividade exp\xf5e para a federa\xe7\xe3o mais ampla. Voc\xea toca seus projetos, e seus dados, do seu pr\xf3prio jeito."],"openSourceTitle":"C\xf3digo Aberto","openSourceTags":["Pode Ser Auto-hospedado","Guiado pela Comunidade","Transparente","Livre como em Liberdade"],"openSource":["O Cocoso \xe9 um software livre e de c\xf3digo aberto, desenvolvido \xe0s claras — voc\xea pode ler cada linha dele, rodar no seu pr\xf3prio servidor, ou confiar em uma hospedagem da sua escolha. Sem depend\xeancia de fornecedor, sem caixa-preta.","Ele \xe9 moldado pelas comunidades que o usam: artistas, cooperativas, projetos de moeda alternativa e espa\xe7os de cocria\xe7\xe3o que devolvem necessidades reais ao projeto desde seus primeiros dias."],"ctaTitle":"Veja Tudo que o Cocoso Pode Fazer","ctaBody":"Do calend\xe1rio ao painel de administra\xe7\xe3o, cada funcionalidade foi pensada para ser usada por uma comunidade, n\xe3o por um webmaster. Explore o que tem por aqui.","ctaButton":"Explorar Funcionalidades","ctaSecondary":"Ou s\xf3 d\xe1 um oi"},"features":{"pageTitle":"Funcionalidades","pageLead":"O Cocoso em detalhes — cada ferramenta que sua comunidade pode usar, e como ela funciona.","groupCommunityTitle":"Para a Sua Comunidade","groupAdminTitle":"Para Administradores","activityTitle":"Atividades","activityTags":["Eventos P\xfablicos","Confirma\xe7\xe3o de Presen\xe7a","Trabalhos em Andamento","Apresenta\xe7\xf5es","Exposi\xe7\xf5es","Shows","Confer\xeancias","Internos","Reservas"],"activities":["A primeira vers\xe3o do Cocoso foi criada para um teatro de dan\xe7a autogerido por artistas e um espa\xe7o de coaprendizagem, que recebia diversas apresenta\xe7\xf5es p\xfablicas para um p\xfablico inscrito previamente. Gerenciar e publicar eventos personaliz\xe1veis e recorrentes exige v\xe1rias funcionalidades diferentes, incluindo a confirma\xe7\xe3o de presen\xe7a. As inscri\xe7\xf5es s\xe3o comunicadas aos convidados por e-mail, e os administradores do evento podem verificar as chegadas na porta.","Voc\xea pode criar, editar e excluir conte\xfado com uma imagem, t\xedtulo, descri\xe7\xe3o e mais informa\xe7\xf5es, al\xe9m de um conjunto de datas e hor\xe1rios opcionalmente m\xfaltiplos — assim os administradores nunca precisam criar uma entrada nova para cada ocorr\xeancia."],"resourceTitle":"Recursos","resourceTags":["Compartilhamento de Recursos","Gest\xe3o de Bens Comuns"],"resources":["O Cocoso permite planejar e ter uma vis\xe3o geral dos processos de compartilhamento de recursos em tempo h\xe1bil. Toda vez que um usu\xe1rio verificado reserva um recurso f\xedsico ou um espa\xe7o, essa informa\xe7\xe3o \xe9 compartilhada com os membros do coletivo atrav\xe9s do calend\xe1rio.","N\xe3o existem convites de calend\xe1rio. Acreditamos que as m\xe1quinas devem nos ajudar a facilitar nossa pr\xf3pria comunica\xe7\xe3o e compartilhamento — n\xe3o agir no nosso lugar. O calend\xe1rio do Cocoso \xe9 a principal vitrine dos eventos da comunidade e do compartilhamento de recursos, para continuarmos conversando uns com os outros, do mesmo jeito que livramos nossos e-mails da bagun\xe7a de dados."],"calendarTitle":"Calend\xe1rio","calendarTags":["Agendamento","Agenda","Compartilhamento de Bens Comuns","Programa\xe7\xe3o de Atividades","Reservas de Recursos"],"calendar":["O calend\xe1rio web do Cocoso pode mostrar eventos e atualiza\xe7\xf5es de recursos mensais, semanais ou di\xe1rios, e os usu\xe1rios navegam entre esses per\xedodos com um \xfanico toque. Cada entrada pode corresponder a uma atividade de uso de recursos ou a um evento da comunidade.","Cada entrada pode receber uma categoria — um recurso reservado, ou um tipo de atividade como ioga — \xfatil tanto para listagens p\xfablicas de atividades quanto para reservas internas ou privadas. Como toda funcionalidade do Cocoso, ela \xe9 propositalmente abstrata para se encaixar em usos bem diferentes."],"groupTitle":"Grupos","groupTags":["Grupos de Estudo","Escolas","Cocria\xe7\xe3o","Eventos Recorrentes","Documentos Compartilhados","Atividades de Membros"],"groups":["Um Grupo \xe9 um conceito, e um conjunto de atividades conceitualmente conectadas, conduzidas por um conjunto de pessoas — virtualmente ou presencialmente. Dentro de um grupo, os membros podem realizar atividades colaborativas com todos os detalhes pr\xe1ticos, informa\xe7\xf5es b\xe1sicas e datas documentados em uma \xfanica p\xe1gina.","Os grupos permitem gerenciar treinamentos, atividades sociais ou de aprendizagem — sess\xf5es recorrentes de ioga, semestres escolares, ou qualquer tipo de cocria\xe7\xe3o e processo em constante evolu\xe7\xe3o. Os administradores criam um grupo com uma imagem e um texto, e um f\xf3rum simples, uma lista de documentos, uma lista de membros e um conjunto de datas ficam prontos em uma \xfanica p\xe1gina.","\xc9 basicamente o conjunto de ferramentas para tocar uma escola, uma sess\xe3o recorrente, ou uma atividade cooperativa de qualquer tipo."],"workTitle":"Trabalhos","workTags":["Portf\xf3lio","Marketplace","Documenta\xe7\xe3o","Apresenta\xe7\xe3o"],"works":["Um Trabalho \xe9 uma cria\xe7\xe3o visual, ou audiovisual, de um artista, pesquisador, designer, artes\xe3o ou revendedor, apresentada para a comunidade. Detalhes, imagens, arquivos de \xe1udio e v\xeddeos podem ser compartilhados dentro de uma categoria escolhida pelo criador — uma ferramenta pensada tanto para portf\xf3lios quanto para marketplaces.","Um trabalho tamb\xe9m pode ser salvo de forma privada, para uso interno e documenta\xe7\xe3o. Ele foi criado para permitir que artistas e artes\xe3os publiquem e comuniquem o que fazem para o resto do mundo, al\xe9m de manter um registro para refer\xeancia pr\xf3pria."],"memberTitle":"Membros","memberTags":["Gerenciar Membros","Comunidade","Associa\xe7\xf5es","Verifica\xe7\xe3o","Pap\xe9is e Privil\xe9gios","Seguidores"],"members":["Os administradores conseguem encontrar, filtrar e gerenciar cada membro da organiza\xe7\xe3o em um s\xf3 lugar: verificar ou remover a verifica\xe7\xe3o de pessoas para habilidades espec\xedficas, como publicar atividades no calend\xe1rio ou criar um grupo.","Se voc\xea toca um est\xfadio de ioga, por exemplo, vai ter professores e alunos na mesma plataforma — verifique seus professores para que possam criar suas pr\xf3prias atividades, enquanto os alunos apenas participam e confirmam presen\xe7a.","Os privil\xe9gios s\xe3o distribu\xeddos de forma significativa por toda a comunidade, e cada usu\xe1rio cria e gerencia sua pr\xf3pria conta. As senhas s\xe3o automaticamente criptografadas, ent\xe3o os administradores do sistema n\xe3o conseguem l\xea-las nem rastre\xe1-las."],"pagesTitle":"P\xe1ginas Compon\xedveis","pagesTags":["Arrastar e Soltar","Landing Pages","Campanhas","P\xe1ginas Est\xe1ticas","Sem C\xf3digo"],"pages":["Monte livremente uma landing page, uma p\xe1gina de campanha, ou qualquer p\xe1gina est\xe1tica que a sua comunidade precisar — com blocos de arrastar e soltar para texto, imagens e layout, sem precisar escrever c\xf3digo. O que antes era o CMS mais simples do Cocoso agora \xe9 um verdadeiro construtor de p\xe1ginas.","Cada p\xe1gina vira automaticamente parte da sua navega\xe7\xe3o. Use para uma p\xe1gina Sobre N\xf3s, um conjunto de termos, uma campanha pontual, ou uma se\xe7\xe3o totalmente nova do seu site — montada livremente, publicada na hora."],"adminTitle":"Painel de Administra\xe7\xe3o","adminTags":["Configura\xe7\xe3o da Organiza\xe7\xe3o","Identidade Visual","Menu e Navega\xe7\xe3o","Cabe\xe7alho e Rodap\xe9","Configura\xe7\xf5es"],"admin":["Um painel de administra\xe7\xe3o dedicado para configurar sua organiza\xe7\xe3o do zero: nome, logo, dados de contato, e todas as configura\xe7\xf5es que definem como a sua comunidade se apresenta — sem precisar escrever c\xf3digo.","Personalize seu menu, cabe\xe7alho e rodap\xe9, e decida exatamente o que os visitantes veem primeiro. \xc9 a sala de controle por tr\xe1s de cada comunidade Cocoso, feita para administradores, n\xe3o para desenvolvedores."],"designTitle":"Prefer\xeancias de Design","designTags":["Cores","Raio das Bordas","Fundos","Visual e Estilo"],"design":["D\xea ao site da sua comunidade uma identidade visual pr\xf3pria: escolha suas cores, ajuste o raio das bordas, defina um fundo — deixe com a sua cara, sem tocar em uma \xfanica linha de CSS.","As prefer\xeancias de design se aplicam a todo o seu site de uma vez, para que a presen\xe7a da sua comunidade continue coerente conforme ela cresce, da p\xe1gina inicial ao calend\xe1rio, passando por cada p\xe1gina compon\xedvel."],"newsletterTitle":"Newsletter e E-mails","newsletterTags":["Newsletter por E-mail","E-mails Autom\xe1ticos","Comunica\xe7\xe3o com Membros"],"newsletter":["Alcance cada membro diretamente com uma newsletter por e-mail — sem precisar de uma ferramenta separada de lista de e-mails. Escreva uma vez, envie para toda a sua comunidade, e mantenha todo mundo informado sem depender de uma rede social.","E-mails autom\xe1ticos cuidam dos momentos de rotina para voc\xea: confirma\xe7\xf5es de inscri\xe7\xe3o, verifica\xe7\xf5es de presen\xe7a e outras notifica\xe7\xf5es para membros s\xe3o enviadas sozinhas, para que os administradores possam focar na comunidade em vez da caixa de entrada."]},"clients":{"pageTitle":"Casos de Uso","pageLead":"Comunidades, est\xfadios e artistas de verdade que j\xe1 usam o Cocoso — redes federadas, espa\xe7os de trabalho compartilhados, calend\xe1rios de eventos e portf\xf3lios pessoais, cada um do seu jeito.","samarbetetTitle":"Samarbetet","samarbetetTags":["Su\xe9cia","Federa\xe7\xe3o","Artistas e Espa\xe7os Culturais"],"samarbetet":["O Samarbetet \xe9 uma federa\xe7\xe3o de comunidades independentes por toda a Su\xe9cia — artistas, espa\xe7os de arte, jardins, oficinas e pessoas, conectados em uma mesma rede compartilhada.","Os membros compartilham palcos, jardins, oficinas e espa\xe7os de encontro, tocam seus pr\xf3prios programas e lojas, e continuam independentes enquanto aproveitam uma porta de entrada compartilhada para todo o ecossistema."],"samarbetetLinkLabel":"Visitar samarbetet.org","kkvTitle":"KKV Estocolmo","kkvTags":["Reserva de Recursos","200+ Recursos","400+ Membros"],"kkv":["A KKV Estocolmo — Konstn\xe4rernas Kollektivverkstad — \xe9 um espa\xe7o de trabalho coletivo para artistas profissionais, dando a mais de 400 membros acesso compartilhado a mais de 200 equipamentos e espa\xe7os de oficina.","Os membros reservam recursos pelo calend\xe1rio do Cocoso, publicam seus pr\xf3prios portf\xf3lios e eventos p\xfablicos, e se encontram em uma p\xe1gina de membros compartilhada — uma oficina grande e agitada rodando tranquilamente em uma \xfanica plataforma."],"kkvLinkLabel":"Visitar stockholm.kkv.nu","hojdenTitle":"h\xf6jden","hojdenTags":["Espa\xe7o Autogerido por Artistas","Reserva de Recursos","Portf\xf3lios"],"hojden":["O h\xf6jden \xe9 um espa\xe7o autogerido por artistas em Estocolmo — est\xfadios, um palco, uma pista de dan\xe7a, uma galeria e uma cozinha, tocado coletivamente pela cooperativa Sl\xe4ktet desde 2018.","Assim como a KKV, o h\xf6jden usa o Cocoso para gerenciar as reservas de seus espa\xe7os e equipamentos compartilhados, junto com portf\xf3lios de membros e uma programa\xe7\xe3o p\xfablica de oficinas, apresenta\xe7\xf5es e palestras."],"hojdenLinkLabel":"Visitar hojden.house","gerlesborgTitle":"Gerlesborgs Kulturhus","gerlesborgTags":["Centro Cultural","Eventos P\xfablicos","Calend\xe1rio"],"gerlesborg":["O Gerlesborgs kulturhus \xe9 um centro cultural em Hamburgsund, na Su\xe9cia, que recebe exposi\xe7\xf5es, shows, oficinas e um festival de literatura para a comunidade ao redor.","Ele usa o Cocoso de um jeito simples e eficaz para publicar sua programa\xe7\xe3o p\xfablica — cada exposi\xe7\xe3o, show e curso aparece direto no calend\xe1rio, sem precisar de uma ferramenta de eventos separada."],"gerlesborgLinkLabel":"Visitar gerlesborgskulturhus.se","minaTitle":"M\xeena Kocailik","minaTags":["Portf\xf3lio","Artista Independente"],"mina":["M\xeena Kocailik \xe9 uma artista independente que usa o Cocoso simplesmente para publicar seu portf\xf3lio: uma vitrine limpa e autogerenciada do seu trabalho, sem nada extra para manter.","\xc9 o menor uso poss\xedvel do Cocoso — a prova de que a mesma plataforma que atende federa\xe7\xf5es com centenas de pessoas funciona igualmente bem para uma \xfanica pr\xe1tica criativa."],"minaLinkLabel":"Visitar o portf\xf3lio dela"},"credits":{"title":"Cr\xe9ditos","first":"Desenvolvido em uma colabora\xe7\xe3o incr\xedvel com","second":"Com o apoio de"},"contact":{"title":"Contato","heading":"Podemos trabalhar juntos","body":"Voc\xea tem um projeto em que o Cocoso possa ajudar? Ou s\xf3 quer dar um oi e virar nosso amigo? Deixe uma mensagem aqui, e a gente te responde!","email":"Seu endere\xe7o de e-mail","subject":"Assunto","message":"Mensagem","send":"Enviar"},"footer":{"tagline":"Software de c\xf3digo aberto para federa\xe7\xf5es de comunidades, cooperativas e grupos de base — um site p\xfablico e uma intranet privada, sempre nos seus pr\xf3prios termos.","exploreTitle":"Explorar","projectTitle":"Projeto","license":"Livre e de c\xf3digo aberto, licenciado sob a GNU GPLv3.","bottom":"\xa9 {{year}} Cocoso. Criado para comunidades aut\xf4nomas em todo lugar."},"source":"Fonte"}')}}]);